class Ahrara < Formula
  desc "Disposable email with a local inbox for AI agents, QA and automation"
  homepage "https://ahrara.dev"
  license "MIT"

  # BEGIN RELEASE METADATA (generated by scripts/release-manifest.py)
  version "0.1.0"

  on_macos do
    on_arm do
      url "https://github.com/Hitmasu/Ahrara/releases/download/v0.1.0/ahrara-darwin-aarch64", using: :nounzip
      sha256 "4d24911af2771e39ee1b79a1b1d6329472f7139a926bc5d830ada42111b2ca3c"
    end
    on_intel do
      url "https://github.com/Hitmasu/Ahrara/releases/download/v0.1.0/ahrara-darwin-x86_64", using: :nounzip
      sha256 "a75b6cce770512752b249ae76bec28e17737a49bb58ebbd28092a9ab28056be7"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/Hitmasu/Ahrara/releases/download/v0.1.0/ahrara-linux-aarch64", using: :nounzip
      sha256 "f9e814dc3787dffc12ab625ae1f33ead549d3150215ac02384658b6572d6a2b5"
    end
    on_intel do
      url "https://github.com/Hitmasu/Ahrara/releases/download/v0.1.0/ahrara-linux-x86_64", using: :nounzip
      sha256 "0f356f9446adc326e14b4402c5fabd433b6c3b7d6fcd8177817914b54bacf1c6"
    end
  end
  # END RELEASE METADATA

  def install
    libexec.install File.basename(stable.url) => "ahrara"
    chmod 0755, libexec/"ahrara"
    (libexec/"ahrara.install.json").write <<~JSON
      {"schema_version":1,"method":"brew"}
    JSON
    bin.install_symlink libexec/"ahrara"
  end

  test do
    assert_match "ahrara #{version}", shell_output("#{bin}/ahrara --version")
    output = shell_output("#{bin}/ahrara --config #{testpath}/unused/config.toml --json update")
    result = JSON.parse(output)
    assert_equal "brew", result.fetch("install_method")
    assert_equal false, result.fetch("updated")
    assert_match "brew upgrade ahrara", result.fetch("message")
    refute_path_exists testpath/"unused"
  end
end
